mapper.select:
SELECT code, name, spec FROM materials WHERE LOWER(REGEXP_REPLACE(COALESCE(name, ''), '\s', '', 'g')) = LOWER(REGEXP_REPLACE(#{name}, '\s', '', 'g')) AND LOWER(REGEXP_REPLACE(COALESCE(spec, ''), '\s', '', 'g')) = LOWER(REGEXP_REPLACE(COALESCE(#{spec,jdbcType=VARCHAR}, ''), '\s', '', 'g'))
AND code != #{excludeCode}
ORDER BY code

mapper.update:
UPDATE materials
SET
    name = #{row.name},
    client_code = #{row.supplier} 
    , spec = #{row.spec}
    , warehouse_cd = (SELECT wh.warehouse_cd FROM tb_warehouse wh WHERE wh.warehouse_nm = #{row.warehouse} AND wh.factory_code = 'F001' AND wh.plant_code = 'P001' ORDER BY CASE WHEN wh.use_yn = 'Y' THEN 0 ELSE 1 END, wh.warehouse_id LIMIT 1)
    , sub_category = #{row.subCategory}
    , unit = #{row.unit}
    , allergens = #{row.allergens}
    , safety_stock = #{row.safetyStock,jdbcType=DOUBLE}
    , base_order_qty = #{row.baseOrderQty,jdbcType=DOUBLE}
    , unit_weight = #{row.unitWeight,jdbcType=DOUBLE}
    , box_qty = #{row.boxQty,jdbcType=INTEGER}
WHERE code = #{row.code}

UPDATE bom
SET material_name = #{name}
WHERE material_code = #{code}

UPDATE recipe_version_bom
SET material_name = #{name}
WHERE material_code = #{code}

mapper.select:
SELECT COUNT(*)
FROM materials
WHERE name = #{name}

mapper.update:
UPDATE recipe_version_bom
SET
    material_name = #{name},
    material_code = #{code}
WHERE material_code IS NULL
  AND material_name = #{oldName}

mapper.select:
SELECT DISTINCT product_code FROM bom WHERE material_code = #{code}
AND product_code IN #{productCode}
ORDER BY product_code

SELECT COALESCE(SUM(amount_per_kg), 0)
FROM bom
WHERE product_code = #{productCode}

mapper.update:
UPDATE materials
SET unit_price = #{unitPrice,jdbcType=DOUBLE}
WHERE code = #{code}

mapper.delete:
DELETE FROM material_price_schedule
WHERE id = #{id}
  AND applied = 0

mapper.update:
UPDATE material_price_schedule
SET applied = 1
WHERE id = #{id}
